"""Write experiment results to docs/results/<name>.md and .json (generated; do not edit by hand)."""

from __future__ import annotations

import json
from datetime import date
from pathlib import Path

import pandas as pd

RESULTS = Path("docs/results")


def table(df: pd.DataFrame, floatfmt: str = "{:.4f}") -> str:
    cols = list(df.columns)
    out = ["| " + " | ".join(map(str, cols)) + " |", "| " + " | ".join("---" for _ in cols) + " |"]
    for row in df.astype(object).itertuples(index=False):  # object dtype keeps ints as ints
        cells = [floatfmt.format(v) if isinstance(v, float) else str(v) for v in row]
        out.append("| " + " | ".join(cells) + " |")
    return "\n".join(out)


def write(name: str, title: str, sections: list[tuple[str, str]], data: dict, command: str | None = None) -> Path:
    RESULTS.mkdir(parents=True, exist_ok=True)
    command = command or f"python -m startupiq.models.run {name.removesuffix('_test')}" + (" --final" if name.endswith("_test") else "")
    md = [f"# {title}", "", f"Generated by `{command}` on {date.today()}. Do not edit by hand.", ""]
    for heading, body in sections:
        md += [f"## {heading}", "", body, ""]
    path = RESULTS / f"{name}.md"
    path.write_text("\n".join(md), encoding="utf-8")
    (RESULTS / f"{name}.json").write_text(json.dumps(data, indent=2, default=str), encoding="utf-8")
    return path
